from z3 import *
import sys

def search_counterexample(n, W):
    s = Solver()
    # Adjacency
    adj = [[Bool(f"adj_{i}_{j}") for j in range(n)] for i in range(n)]
    for i in range(n):
        s.add(Not(adj[i][i]))
        for j in range(i+1, n):
            s.add(adj[i][j] == adj[j][i])

    # Distance bounds: reach[k][i][j]
    # We need reach up to max(W, n)
    max_k = max(W, n)
    reach = [[[Bool(f"r_{k}_{i}_{j}") for j in range(n)] for i in range(n)] for k in range(max_k+1)]
    for i in range(n):
        for j in range(n):
            if i == j:
                s.add(reach[0][i][j])
            else:
                s.add(Not(reach[0][i][j]))

    for k in range(max_k):
        for i in range(n):
            for j in range(n):
                step = Or([And(reach[k][i][m], adj[m][j]) for m in range(n)])
                s.add(reach[k+1][i][j] == Or(reach[k][i][j], step))

    # Condition: CONNECTED (HasRadius)
    # reach[n-1][i][j] is True for all i, j
    for i in range(n):
        for j in range(n):
            s.add(reach[n-1][i][j])

    # Condition 1: rad(G) >= W
    # For every vertex i, there exists j such that dist(i, j) >= W (i.e. Not(reach[W-1][i][j]))
    for i in range(n):
        s.add(Or([Not(reach[W-1][i][j]) for j in range(n)]))

    # Condition 3: Exists Roman dominating function f with weight <= W
    f = [Int(f"f_{i}") for i in range(n)]
    for i in range(n):
        s.add(Or(f[i] == 0, f[i] == 1, f[i] == 2))
        dom = Or([And(adj[i][j], f[j] == 2) for j in range(n)])
        s.add(Implies(f[i] == 0, dom))

    s.add(Sum(f) <= W)

    res = s.check()
    if res == sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[adj[i][j]]):
                    edges.append((i, j))
        f_vals = [m[f[i]].as_long() for i in range(n)]
        print(f"SAT for n={n}, W={W}! edges={edges}, f={f_vals}")
        return True
    else:
        print(f"UNSAT for n={n}, W={W}")
        return False

print("Running connected Z3 for W=2, 3, 4, 5, 6...")
for W in [2, 3, 4, 5, 6]:
    for n in range(W+1, 12):
        if search_counterexample(n, W):
            print(f"FOUND COUNTEREXAMPLE at n={n}, W={W}!")
            sys.exit(0)
print("All UNSAT!")
